import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, test } from 'vitest';
import { collectInventory, scanSourceInventory } from '../../scripts/permission-inventory.mjs';

// Literal catalog observations from a controlled scenario, not generated by the
// scanner, application guards, permission SQL or candidate role catalog. These
// tests certify tooling transformation only; HTTP/RLS execution is NOT_RUN.
const roleGrant = (principal: string, privilege: string, granted: boolean | null, schemaUsage: boolean | null, extra = {}) => ({
  schema: 'public', object: 'employees', principal, privilege, scope: 'table', column: null,
  granted, schemaUsage, roleExists: principal !== 'anon', ...extra,
});
function fixture() {
  return {
    namespaces: [{ schema: 'public', owner: 'fixture_owner', aclHash: 'namespace-acl' }],
    roles: [{ name: 'authenticated', superuser: false, inherit: true, bypassRls: false, canLogin: false }],
    memberships: [{ role: 'employee_reader', member: 'authenticated', grantor: 'fixture_owner', adminOption: false, inheritOption: 'true', setOption: 'true' }],
    relations: [
      { schema: 'public', object: 'employees', relationKind: 'r', owner: 'fixture_owner', rlsEnabled: true, rlsForced: false, replicaIdentity: 'd', persistence: 'p', isPartition: false, aclHash: 'employee-acl', optionsHash: 'options', viewHash: null, partitionHash: null },
      { schema: 'public', object: 'payments', relationKind: 'r', owner: 'fixture_owner', rlsEnabled: true, rlsForced: false, aclHash: 'payment-acl' },
    ],
    columns: [
      { schema: 'public', object: 'employees', column: 'name', ordinal: 2, type: 'text', notNull: true, identity: '', generated: '', collation: 'default', defaultHash: 'no-default', aclHash: 'name-acl', observerCanSelect: true },
      { schema: 'public', object: 'employees', column: 'id', ordinal: 1, type: 'uuid', notNull: true, identity: '', generated: '', collation: null, defaultHash: 'no-default', aclHash: 'id-acl', observerCanSelect: true },
    ],
    constraints: [{ schema: 'public', object: 'employees', name: 'employees_pkey', type: 'p', validated: true, deferrable: false, deferred: false, definitionHash: 'pk-hash' }],
    indexes: [{ schema: 'public', object: 'employees', name: 'employees_pkey', valid: true, ready: true, unique: true, definitionHash: 'index-hash' }],
    triggers: [{ schema: 'public', object: 'employees', name: 'session_revoke', enabled: 'O', internal: false, definitionHash: 'trigger-hash' }],
    types: [{ schema: 'public', name: 'employee_role', kind: 'e', labels: ['admin', 'cashier', 'kitchen'], aclHash: 'type-acl' }],
    defaultAcls: [{ role: 'fixture_owner', schema: '*', objectType: 'f', aclHash: 'default-function-acl' }],
    tableGrants: [
      roleGrant('anon', 'SELECT', null, null),
      roleGrant('authenticated', 'SELECT', false, true),
      roleGrant('PUBLIC', 'SELECT', false, true, { roleExists: true }),
      roleGrant('authenticated', 'UPDATE', true, true),
      roleGrant('authenticated', 'INSERT', false, true, { object: 'payments' }),
    ],
    columnGrants: [roleGrant('authenticated', 'SELECT', true, true, { scope: 'column', column: 'name' })],
    routines: [
      { schema: 'public', object: 'pay_order', signature: 'p_order_id uuid', routineKind: 'f', securityDefiner: true, bodyHash: 'old-body', definitionHash: 'old-definition', aclHash: 'old-acl' },
      { schema: 'public', object: 'pay_order', signature: 'p_order_id uuid, p_payload jsonb', routineKind: 'f', securityDefiner: false, bodyHash: 'new-body', definitionHash: 'new-definition', aclHash: 'new-acl' },
      { schema: 'private', object: 'helper', signature: '', routineKind: 'f', securityDefiner: true, bodyHash: 'helper-body', definitionHash: 'helper-definition', aclHash: 'default-public-execute' },
    ],
    routineGrants: [
      { schema: 'public', object: 'pay_order', signature: 'p_order_id uuid', principal: 'authenticated', privilege: 'EXECUTE', scope: 'routine', roleExists: true, granted: false, schemaUsage: true },
      { schema: 'public', object: 'pay_order', signature: 'p_order_id uuid, p_payload jsonb', principal: 'authenticated', privilege: 'EXECUTE', scope: 'routine', roleExists: true, granted: true, schemaUsage: true },
      { schema: 'private', object: 'helper', signature: '', principal: 'PUBLIC', privilege: 'EXECUTE', scope: 'routine', roleExists: true, granted: true, schemaUsage: false },
    ],
    policies: [{ schema: 'public', object: 'employees', name: 'tenant_select', command: 'r', permissive: true, roles: ['authenticated'], usingHash: 'tenant-predicate', checkHash: null }],
    publications: [{ name: 'fixture_realtime', owner: 'fixture_owner', allTables: false, insert: true, update: true, delete: true, truncate: false, viaPartitionRoot: false }],
    publicationMembers: [{ publication: 'fixture_realtime', schema: 'public', object: 'payments', columns: ['id', 'amount'], rowFilterHash: null }],
    publicationSchemas: [],
    buckets: [],
  } as Record<string, any[]>;
}
function database(data = fixture()) {
  const calls: { name: string; sql: string; values: unknown[] }[] = [];
  return {
    calls,
    async query(sql: string, values: unknown[]) {
      const name = sql.match(/permission-inventory:(\w+)/)?.[1];
      if (!name || !(name in data)) throw new Error('Unexpected query');
      calls.push({ name, sql, values });
      return { rows: structuredClone(data[name]) };
    },
  };
}

describe('permission inventory tooling: catalog evidence only', () => {
  test('separates table/column grants, denied grants and absent roles without claiming RLS authorization', async () => {
    const { surfaces } = await collectInventory(database());
    const select = surfaces.find((row) => row.surfaceId === 'SELECT:public.employees');
    expect(select.observedGrants).toEqual(expect.arrayContaining([
      { principal: 'anon', privilege: 'SELECT', scope: 'table', column: null, roleExists: false, granted: null, schemaUsage: null, accessible: null },
      { principal: 'authenticated', privilege: 'SELECT', scope: 'table', column: null, roleExists: true, granted: false, schemaUsage: true, accessible: false },
      { principal: 'authenticated', privilege: 'SELECT', scope: 'column', column: 'name', roleExists: true, granted: true, schemaUsage: true, accessible: true },
    ]));
    expect(select.observedGrants.every((row) => row.privilege === 'SELECT')).toBe(true);
    expect(select.policies).toEqual([{ name: 'tenant_select', command: 'r', permissive: true, roles: ['authenticated'], usingHash: 'tenant-predicate', checkHash: null }]);
    const dml = surfaces.find((row) => row.surfaceId === 'DML:public.employees');
    expect(dml.observedGrants.map((row) => [row.principal, row.privilege, row.accessible])).toEqual([['authenticated', 'UPDATE', true]]);
    expect(surfaces.find((row) => row.surfaceId === 'DML:public.payments').expectedProtection).toContain('no direct application financial/ledger DML');
    for (const row of surfaces) expect(row.runtimeVerification).toEqual({ http: 'NOT_RUN', realtime: 'NOT_RUN', employeeAuthorization: 'NOT_RUN' });
  });

  test('preserves every overload and effective PUBLIC execute even without schema usage', async () => {
    const db = database();
    const { surfaces } = await collectInventory(db);
    const overloads = surfaces.filter((row) => row.evidence === 'catalog' && row.kind === 'RPC' && row.object === 'pay_order');
    expect(overloads.map((row) => [row.signature, row.securityDefiner, row.observedGrants[0].granted]).sort()).toEqual([
      ['p_order_id uuid', true, false], ['p_order_id uuid, p_payload jsonb', false, true],
    ].sort());
    expect(surfaces.find((row) => row.surfaceId === 'RPC:private.helper()').observedGrants).toEqual([
      { principal: 'PUBLIC', privilege: 'EXECUTE', scope: 'routine', roleExists: true, granted: true, schemaUsage: false, accessible: false },
    ]);
    const query = db.calls.find((call) => call.name === 'routineGrants')!.sql;
    expect(query).toContain("coalesce(p.proacl,acldefault('f',p.proowner))");
    expect(query).toContain('has_function_privilege(r.oid,p.oid');
    expect(db.calls.find((call) => call.name === 'columnGrants')!.sql).toContain('has_column_privilege(r.oid,c.oid,a.attnum');
  });

  test('returns bucket metadata and publication column filters, without reading Storage objects', async () => {
    const data = fixture();
    data.relations.push({ schema: 'storage', object: 'buckets', relationKind: 'r', rlsEnabled: true, rlsForced: false, aclHash: 'bucket-acl' });
    for (const column of ['id', 'name', 'public']) data.columns.push({ schema: 'storage', object: 'buckets', column, observerCanSelect: true });
    data.buckets = [{ id: 'menu-item-images', name: 'menu-item-images', public: true, file_size_limit: null, allowed_mime_types: null }];
    data.policies.push({ schema: 'storage', object: 'objects', name: 'tenant_upload', command: 'a', permissive: true, roles: ['authenticated'], usingHash: null, checkHash: 'path-check' });
    const db = database(data);
    const { surfaces } = await collectInventory(db);
    expect(surfaces.find((row) => row.surfaceId === 'Storage:storage.bucket:menu-item-images')).toMatchObject({
      evidence: 'catalog', metadataStatus: 'CATALOG_METADATA_ONLY', bucket: { public: true },
      policies: [{ name: 'tenant_upload', command: 'a', checkHash: 'path-check' }],
      runtimeVerification: { http: 'NOT_RUN' },
    });
    expect(surfaces.find((row) => row.surfaceId === 'publication:public.payments(fixture_realtime)').membership).toEqual({
      publication: 'fixture_realtime', schema: 'public', object: 'payments', columns: ['id', 'amount'], rowFilterHash: null,
    });
    expect(db.calls.find((call) => call.name === 'buckets')!.sql).toBe('/* permission-inventory:buckets */ select "id","name","public",null as "file_size_limit",null as "allowed_mime_types" from storage.buckets');
    expect(db.calls.some((call) => /\bfrom\s+(?:auth\.|storage\.objects)/i.test(call.sql))).toBe(false);
  });

  test('does not query unavailable bucket metadata or treat its absence as a security pass', async () => {
    const data = fixture();
    data.relations.push({ schema: 'storage', object: 'buckets', relationKind: 'r' });
    data.columns.push({ schema: 'storage', object: 'buckets', column: 'id', observerCanSelect: false });
    const db = database(data);
    const { surfaces } = await collectInventory(db);
    expect(db.calls.some((call) => call.name === 'buckets')).toBe(false);
    expect(surfaces.find((row) => row.surfaceId === 'Storage:storage.buckets')).toMatchObject({ metadataStatus: 'METADATA_ACCESS_NOT_AVAILABLE', runtimeVerification: { http: 'NOT_RUN' } });
  });

  test('fingerprint is independent of catalog result order and changes on protected schema drift', async () => {
    const baseline = fixture();
    const first = await collectInventory(database(baseline));
    const reversed = Object.fromEntries(Object.entries(baseline).map(([key, rows]) => [key, rows.toReversed().map((row) => Object.fromEntries(Object.entries(row).reverse()))]));
    expect((await collectInventory(database(reversed))).catalogHash).toBe(first.catalogHash);
    expect(first.catalogHash).toMatch(/^[a-f0-9]{64}$/);
    for (const [section, key] of [
      ['namespaces', 'aclHash'], ['roles', 'bypassRls'], ['memberships', 'inheritOption'],
      ['relations', 'rlsForced'], ['columns', 'defaultHash'], ['columns', 'type'],
      ['constraints', 'definitionHash'], ['indexes', 'definitionHash'], ['triggers', 'enabled'],
      ['types', 'labels'], ['defaultAcls', 'aclHash'], ['routines', 'bodyHash'],
      ['routines', 'aclHash'], ['policies', 'usingHash'], ['publications', 'allTables'],
      ['publicationMembers', 'rowFilterHash'],
    ]) {
      const changed = structuredClone(baseline);
      changed[section][0][key] = 'CONTROLLED_SCHEMA_DRIFT';
      expect((await collectInventory(database(changed))).catalogHash, `${section}.${key}`).not.toBe(first.catalogHash);
    }
  });

  test('queries metadata only, hashes definitions in PostgreSQL and sanitizes driver failures', async () => {
    const db = database();
    await collectInventory(db);
    for (const { sql } of db.calls) {
      expect(sql.replace(/^\/\*[\s\S]*?\*\//, '').trim()).toMatch(/^(select|with)\b/i);
      expect(sql).not.toMatch(/\b(?:begin|commit|rollback|set\s+role|set_config)\b/i);
    }
    const routineSql = db.calls.find((call) => call.name === 'routines')!.sql;
    expect(routineSql).toContain('md5(p.prosrc)');
    expect(routineSql).toContain('md5(pg_get_functiondef(p.oid))');
    const failure = { async query() { throw Object.assign(new Error('postgres://user:DO_NOT_DISCLOSE@remote/private'), { code: '42501' }); } };
    await expect(collectInventory(failure)).rejects.toThrow('Permission inventory failed at namespaces; SQLSTATE 42501');
    await expect(collectInventory(failure)).rejects.not.toThrow('DO_NOT_DISCLOSE');
  });
});

describe('permission inventory static consumers', () => {
  test('discovers known direct reads/DML, wrapped RPC, Realtime and Storage without claiming deployment', () => {
    const surfaces = scanSourceInventory();
    const expected = [
      ['SELECT', 'employees', 'src/adapters/supabase/employeeRepo.ts'],
      ['DML', 'employees', 'src/adapters/supabase/employeeRepo.ts'],
      ['DML', 'menu_items', 'src/adapters/supabase/menuRepo.ts'],
      ['RPC', 'register_write_operation', 'src/adapters/supabase/writeOperationRepo.ts'],
      ['RPC', 'get_payment_receipt', 'supabase/migrations/016_activate_write_protocol.sql'],
      ['Storage', 'menu-item-images', 'src/adapters/supabase/menuImagePort.ts'],
      ['publication', 'store_change_signals', 'src/adapters/supabase/realtimePort.ts'],
    ];
    for (const [kind, object, file] of expected) {
      const row = surfaces.find((candidate) => candidate.kind === kind && candidate.object === object);
      expect(row, `${kind}:${object}`).toBeDefined();
      expect(row).toMatchObject({ evidence: 'static', observedGrants: [], runtimeVerification: { http: 'NOT_RUN', realtime: 'NOT_RUN' } });
      const ref = row.source.find((candidate) => candidate.file === file);
      expect(ref, file).toBeDefined();
      expect(ref.line).toBeGreaterThan(0);
      expect(readFileSync(resolve(file), 'utf8').split('\n')[ref.line - 1]).toBeTruthy();
    }
    expect(surfaces.some((row) => row.object === '<dynamic:table>')).toBe(true);
    // PERM-T10 / TC-PERM-29: this adapter subscribes only to metadata signals,
    // then refetches permitted projections; no business-row subscription may
    // return here, including the deliberately unsupported join-only stream.
    const realtimeSubscriptions = surfaces.filter((row) => row.kind === 'publication'
      && row.source.some((ref) => ref.file === 'src/adapters/supabase/realtimePort.ts'));
    expect(realtimeSubscriptions.map((row) => [row.schema, row.object])).toEqual([
      ['public', 'store_change_signals'],
    ]);
  });
});
